import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"旋涂与厚度均匀性","description":"","frontmatter":{"title":"旋涂与厚度均匀性","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/spin-coating-uniformity.md","filePath":"litho/spin-coating-uniformity.md","lastUpdated":1789023840000}'),c={name:"litho/spin-coating-uniformity.md"};function E(m,a,_,f,u,B){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="旋涂与厚度均匀性" tabindex="-1">旋涂与厚度均匀性 <a class="header-anchor" href="#旋涂与厚度均匀性" aria-label="Permalink to &quot;旋涂与厚度均匀性&quot;">​</a></h1><div class="epigraph"><p>胶厚不是配方桶上的标称纳米数，是转速、粘度和排气把液膜拉成的径向剖面。窗口里的剂量对厚度敏感，均匀性先于 OPC。</p><footer>—— 据 Mack / Levinson 对 spin coating 与摆动曲线的论述整理</footer></div><p><a href="/litho/dry-resist-develop">上一课</a>把干法显影胶钉成随机性课序的收束。本课是补层「涂胶显影与轨道」第一课：成像与胶化学已经在主干里，缺口转到<strong>曝光前液膜怎么铺成可重复的厚度</strong>。后课 EBR、三层、软烤都默认你会旋涂剖面，不再从 Dill 或瑞利讲起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/swing-curve">摆动曲线</a> 与 <a href="/litho/resist-thickness-selection">胶厚选择</a> 假定厚度 \\(d\\) 是一个数。轨道上 \\(d=d(r)\\)：中心厚、边缘珠、缺口处的彗尾。CD 对 \\(d\\) 的敏感经过驻波与吸收，径向几个纳米就能把剂量窗口吃掉。把 CDU 全写成扫描仪剂量，是把涂胶误差派给曝光。</p><p>缺口因此是旋涂的控制量：粘度、滴胶量、转速–时间曲线、加速度、杯内气流与排气。不写这些，后课热板与缺陷没有厚度这个前置。</p><p><span class="marginnote">静态滴胶后的加速段决定气泡与条纹；匀速段决定平均厚度。只报最终 rpm、不报加速度，复制不了剖面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工艺窗口用「目标 \\(d\\) ± 规格」加径向扫描（椭偏或光谱）。转速升高，离心力增大，平均厚度下降，近似随 \\(\\omega\\) 的幂次减薄（经验幂因胶而异）。边缘珠另课切除。缺口、标记、已有形貌会改局部流场——前层拓扑不是旋涂课能抹平的，要靠 BARC 与平坦化。</p>',9)),(e(),s(h,null,{default:i(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E6%BB%B4%E8%83%B6%22%5D%20--%3E%20SPIN%5B%22%E5%8A%A0%E9%80%9F%E4%B8%8E%E5%8C%80%E9%80%9F%22%5D%0A%20%20SPIN%20--%3E%20PROF%5B%22%E5%BE%84%E5%90%91%E5%8E%9A%E5%BA%A6%20d(r)%22%5D%0A%20%20PROF%20--%3E%20EBR%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8E%BB%E7%8F%A0%22%5D%0A%20%20PROF%20--%3E%20SWING%5B%22%E9%A9%BB%E6%B3%A2%20%2F%20%E6%91%86%E5%8A%A8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>液膜在旋转坐标系里受离心、粘滞与表面张力。挥发性溶剂在旋的过程中走，粘度随时间升，剖面被「冻」在软烤前。排气过强会局部干边；过弱则溶剂氛不均。同一标称 rpm，杯盖与温湿度变了，等价于换胶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写喷墨或狭缝涂布的面板级替代。不重写 <a href="/litho/standing-wave-barc">驻波与 BARC</a> 的干涉公式。下一课只切边缘珠，不改中心厚度设定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>旋涂给出 \\(d(r)\\)，不是桶上的标称厚度。</li><li>CDU 有一块来自径向剖面与排气，不是全是剂量。</li><li>加速度与气流与 rpm 同为一等参数。</li><li>出处：Mack / Levinson 对旋涂与厚度的工艺论述。</li></ul>',6))])}const g=o(c,[["render",E]]);export{P as __pageData,g as default};
